const JSON_HEADERS = {
  "content-type": "application/json; charset=utf-8",
  "access-control-allow-origin": "*",
  "access-control-allow-methods": "GET,POST,PATCH,DELETE,OPTIONS",
  "access-control-allow-headers": "content-type,authorization,x-admin-token,x-collector-token"
};
const json=(data,status=200,headers={})=>new Response(JSON.stringify(data),{status,headers:{...JSON_HEADERS,...headers}});
const html=(body,status=200)=>new Response(body,{status,headers:{"content-type":"text/html; charset=utf-8"}});
const clean=(s="")=>String(s).trim().replace(/\s+/g," ");
const codeNormalize=(s="")=>String(s).trim();
async function sha256Hex(value){const data=new TextEncoder().encode(value);const digest=await crypto.subtle.digest("SHA-256",data);return [...new Uint8Array(digest)].map(b=>b.toString(16).padStart(2,"0")).join("");}
function randomCode(){const bytes=new Uint8Array(18);crypto.getRandomValues(bytes);return "XPH-"+[...bytes].map(b=>b.toString(16).padStart(2,"0")).join("").toUpperCase();}
const preview=(s="",n=320)=>clean(s).slice(0,n);
const clamp=(n,min,max)=>Math.min(Math.max(Number(n||min),min),max);
const hasCJK=(s="")=>/[\u3400-\u9fff\uf900-\ufaff]/.test(s);
const esc=(s="")=>String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");
const like=(s="")=>`%${String(s).replace(/[%_]/g,c=>`\\${c}`)}%`;
function authToken(req,name){return req.headers.get(name)||req.headers.get("authorization")?.replace(/^Bearer\s+/i,"")||"";}
function adminRole(req,env){const token=authToken(req,"x-admin-token");if(env.ADMIN_TOKEN&&token===env.ADMIN_TOKEN)return "super_admin";if(env.STAFF_ADMIN_TOKEN&&token===env.STAFF_ADMIN_TOKEN)return "admin";return "";}
function requireAdmin(req,env){return Boolean(adminRole(req,env));}
function requireSuperAdmin(req,env){return adminRole(req,env)==="super_admin";}
function requireCollector(req,env){return Boolean(env.COLLECTOR_TOKEN&&authToken(req,"x-collector-token")===env.COLLECTOR_TOKEN);}
async function tg(env,method,body){if(!env.BOT_TOKEN)throw new Error("BOT_TOKEN is not configured");const r=await fetch(`https://api.telegram.org/bot${env.BOT_TOKEN}/${method}`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(body)});return r.json();}
function messageUrl(x){return x.message_url||"";}
function resultText(x,i=0){const title=esc(x.channel_title|| (x.channel_username?`@${x.channel_username}`:"频道内容"));const body=esc(preview(x.text||`[${mediaLabel(x.media_type)}]`));const date=x.published_at?new Date(x.published_at).toLocaleString("zh-CN",{timeZone:"Asia/Shanghai"}):"未知时间";const url=messageUrl(x);const media=mediaBadge(x);return `<b>${i+1}. ${title}</b>\n${body}\n<code>${date}</code>${media}${url?`\n<a href="${esc(url)}">查看原文 →</a>`:""}`;}
function mediaLabel(t=""){if(!t)return "文字";if(/photo/i.test(t))return "图片";if(/video/i.test(t))return "视频";if(/document/i.test(t))return "文件";if(/audio|voice/i.test(t))return "音频";if(/webpage/i.test(t))return "链接预览";return "媒体";}
function formatBytes(n){const x=Number(n||0);if(!x)return "";if(x<1024)return `${x} B`;if(x<1048576)return `${(x/1024).toFixed(1)} KB`;if(x<1073741824)return `${(x/1048576).toFixed(1)} MB`;return `${(x/1073741824).toFixed(1)} GB`;}
function mediaBadge(x){if(!x.media_type)return "";const size=formatBytes(x.media_size);return `\n📎 <b>${esc(mediaLabel(x.media_type))}</b>${x.media_name?` · ${esc(x.media_name)}`:""}${size?` · ${size}`:""}`;}
function mediaSqlFilter(media){return media?" AND m.media_type = ?":"";}
async function search(env,p={}){
  const q=clean(p.q||"");const limit=clamp(p.limit,1,20);const offset=Math.max(Number(p.offset||0),0);const channel=clean(p.channel||"").replace(/^@/,"");const from=clean(p.from||"");const to=clean(p.to||"");const media=clean(p.media||"");
  if(!q)return {results:[],total:0,offset,limit,has_more:false};
  const filters=[];const binds=[];if(channel){filters.push("(m.channel_username=? OR m.channel_id=?)");binds.push(channel,channel);}if(from){filters.push("m.published_at>=?");binds.push(from);}if(to){filters.push("m.published_at<=?");binds.push(to.includes("T")?to:`${to}T23:59:59`);}if(media){filters.push("m.media_type=?");binds.push(media);}const where=filters.length?` AND ${filters.join(" AND ")}`:"";
  let rows=[],total=0;
  if(!hasCJK(q)){
    try{const tokens=q.split(/\s+/).filter(Boolean).map(x=>`"${x.replace(/"/g,'""')}"`).join(" ");const r=await env.DB.prepare(`SELECT m.channel_id,m.channel_username,m.channel_title,m.message_id,m.published_at,m.edited_at,m.text,m.media_type,m.media_name,m.media_size,m.message_url FROM messages m JOIN messages_fts f ON f.rowid=m.id WHERE messages_fts MATCH ?${where} ORDER BY bm25(messages_fts),m.published_at DESC LIMIT ? OFFSET ?`).bind(tokens,...binds,limit,offset).all();rows=r.results||[];const c=await env.DB.prepare(`SELECT COUNT(*) total FROM messages m JOIN messages_fts f ON f.rowid=m.id WHERE messages_fts MATCH ?${where}`).bind(tokens,...binds).first();total=Number(c?.total||0);}catch(_){}}
  if(hasCJK(q)||!total){const l=like(q);const c=await env.DB.prepare(`SELECT COUNT(*) total FROM messages m WHERE (m.text LIKE ? ESCAPE '\\' OR m.channel_username LIKE ? ESCAPE '\\' OR m.channel_title LIKE ? ESCAPE '\\')${where}`).bind(l,l,l,...binds).first();total=Number(c?.total||0);const r=await env.DB.prepare(`SELECT m.channel_id,m.channel_username,m.channel_title,m.message_id,m.published_at,m.edited_at,m.text,m.media_type,m.media_name,m.media_size,m.message_url FROM messages m WHERE (m.text LIKE ? ESCAPE '\\' OR m.channel_username LIKE ? ESCAPE '\\' OR m.channel_title LIKE ? ESCAPE '\\')${where} ORDER BY m.published_at DESC,m.message_id DESC LIMIT ? OFFSET ?`).bind(l,l,l,...binds,limit,offset).all();rows=r.results||[];}
  return {results:rows,total,offset,limit,has_more:offset+rows.length<total};
}
async function latest(env,p={}){const limit=clamp(p.limit,1,20);const offset=Math.max(Number(p.offset||0),0);const channel=clean(p.channel||"").replace(/^@/,"");const media=clean(p.media||"");const filters=[];const binds=[];if(channel){filters.push("(channel_username=? OR channel_id=?)");binds.push(channel,channel);}if(media){filters.push("media_type=?");binds.push(media);}const where=filters.length?` WHERE ${filters.join(" AND ")}`:"";const r=await env.DB.prepare(`SELECT channel_id,channel_username,channel_title,message_id,published_at,edited_at,text,media_type,media_name,media_size,message_url FROM messages${where} ORDER BY published_at DESC,message_id DESC LIMIT ? OFFSET ?`).bind(...binds,limit,offset).all();const c=await env.DB.prepare(`SELECT COUNT(*) total FROM messages${where}`).bind(...binds).first();const total=Number(c?.total||0);return {results:r.results||[],total,offset,limit,has_more:offset+(r.results||[]).length<total};}
async function channels(env,enabledOnly=true){const where=enabledOnly?" WHERE enabled=1":"";const r=await env.DB.prepare(`SELECT id,telegram_id,username,title,enabled,last_message_id,message_count,last_synced_at,created_at,updated_at FROM channels${where} ORDER BY title ASC,username ASC`).all();return r.results||[];}
async function saveSession(env,chatId,d){await env.DB.prepare(`INSERT INTO bot_sessions(chat_id,q,channel,from_date,to_date,media,offset,mode,updated_at) VALUES(?,?,?,?,?,?,?,?,CURRENT_TIMESTAMP) ON CONFLICT(chat_id) DO UPDATE SET q=excluded.q,channel=excluded.channel,from_date=excluded.from_date,to_date=excluded.to_date,media=excluded.media,offset=excluded.offset,mode=excluded.mode,updated_at=CURRENT_TIMESTAMP`).bind(String(chatId),d.q||"",d.channel||"",d.from||"",d.to||"",d.media||"",Number(d.offset||0),d.mode||"search").run();}
async function getSession(env,chatId){return env.DB.prepare("SELECT * FROM bot_sessions WHERE chat_id=?").bind(String(chatId)).first();}
function searchKeyboard(data){const nav=[];if(data.offset>0)nav.push({text:"‹ 上一页",callback_data:"search:prev"});if(data.has_more)nav.push({text:"下一页 ›",callback_data:"search:next"});const k=[];if(nav.length)k.push(nav);k.push([{text:"🔎 重新搜索",callback_data:"search:again"},{text:"📚 频道",callback_data:"channels:0"},{text:"🆕 最新",callback_data:"latest:0"}]);return {inline_keyboard:k};}
async function sendSearch(env,chatId,data,editId=null){const page=Math.floor(data.offset/data.limit)+1;const pages=data.total?Math.ceil(data.total/data.limit):0;const header=data.total?`🔎 <b>搜索结果</b>\n关键词：<code>${esc(data.q)}</code>\n第 ${page}/${pages} 页 · 共 ${data.total} 条\n\n`:`🔎 <b>搜索结果</b>\n关键词：<code>${esc(data.q)}</code>\n\n没有找到匹配内容。`;const body=data.results.map((x,i)=>resultText(x,data.offset+i)).join("\n\n");const payload={chat_id:chatId,text:header+body,parse_mode:"HTML",disable_web_page_preview:true,reply_markup:searchKeyboard(data)};return editId?tg(env,"editMessageText",{...payload,message_id:editId}):tg(env,"sendMessage",payload);}
async function sendChannels(env,chatId,offset=0,editId=null){const all=await channels(env,true);const page=all.slice(offset,offset+8);const rows=page.map(x=>[{text:`${x.title||x.username} · ${x.message_count||0}条`,callback_data:`channel:${x.username||x.telegram_id}`}]);const nav=[];if(offset>0)nav.push({text:"‹ 上一页",callback_data:`channels:${Math.max(0,offset-8)}`});if(offset+8<all.length)nav.push({text:"下一页 ›",callback_data:`channels:${offset+8}`});if(nav.length)rows.push(nav);rows.push([{text:"🔎 搜索",callback_data:"search:again"},{text:"🆕 最新",callback_data:"latest:0"}]);const payload={chat_id:chatId,text:"📚 <b>可检索频道</b>\n请选择频道：",parse_mode:"HTML",reply_markup:{inline_keyboard:rows}};return editId?tg(env,"editMessageText",{...payload,message_id:editId}):tg(env,"sendMessage",payload);}
async function sendLatest(env,chatId,offset=0,editId=null){const d=await latest(env,{limit:8,offset});const body=d.results.map((x,i)=>resultText(x,offset+i)).join("\n\n");const nav=[];if(offset>0)nav.push({text:"‹ 上一页",callback_data:`latest:${Math.max(0,offset-8)}`});if(d.has_more)nav.push({text:"下一页 ›",callback_data:`latest:${offset+8}`});const rows=[];if(nav.length)rows.push(nav);rows.push([{text:"🔎 搜索",callback_data:"search:again"},{text:"📚 频道",callback_data:"channels:0"}]);const payload={chat_id:chatId,text:`🆕 <b>最新内容</b>\n第 ${Math.floor(offset/8)+1}/${Math.max(1,Math.ceil(d.total/8))} 页 · 共 ${d.total} 条\n\n${body||"暂无已采集内容。"}`,parse_mode:"HTML",disable_web_page_preview:true,reply_markup:{inline_keyboard:rows}};return editId?tg(env,"editMessageText",{...payload,message_id:editId}):tg(env,"sendMessage",payload);}
async function handleCallback(update,env){const cb=update.callback_query;if(!cb?.message?.chat?.id)return json({ok:true});const chatId=cb.message.chat.id;await tg(env,"answerCallbackQuery",{callback_query_id:cb.id});const d=cb.data||"";if(d==="search:again"){await tg(env,"sendMessage",{chat_id:chatId,text:"请输入 /search 关键词\n例如：/search AI 工具\n指定频道：/search @ai_tools AI 工具"});return json({ok:true});}if(d==="search:prev"||d==="search:next"){const s=await getSession(env,chatId);if(!s)return json({ok:true});const next=Math.max(0,Number(s.offset||0)+(d==="search:next"?8:-8));const r=await search(env,{q:s.q,channel:s.channel,from:s.from_date,to:s.to_date,media:s.media,limit:8,offset:next});await saveSession(env,chatId,{q:s.q,channel:s.channel,from:s.from_date,to:s.to_date,media:s.media,offset:r.offset,mode:"search"});await sendSearch(env,chatId,{...r,q:s.q},cb.message.message_id);return json({ok:true});}if(d.startsWith("latest:")){await sendLatest(env,chatId,Math.max(0,Number(d.split(":")[1]||0)),cb.message.message_id);return json({ok:true});}if(d.startsWith("channels:")){await sendChannels(env,chatId,Math.max(0,Number(d.split(":")[1]||0)),cb.message.message_id);return json({ok:true});}if(d.startsWith("channel:")){const c=d.slice(8);await tg(env,"sendMessage",{chat_id:chatId,text:`已选择频道 @${esc(c)}\n\n请输入：/search 关键词\n例如：/search AI 工具\n或：/search @${esc(c)} AI 工具`,parse_mode:"HTML"});return json({ok:true});}return json({ok:true});}
async function handleWebhook(req,env){const u=await req.json();if(u.callback_query)return handleCallback(u,env);const msg=u.message;if(!msg?.chat?.id||!msg.text)return json({ok:true});const chatId=msg.chat.id;const text=msg.text.trim();if(text==="/start"||text==="/help"){try{await tg(env,"setMyCommands",{commands:[{command:"start",description:"开始使用"},{command:"search",description:"搜索历史内容"},{command:"latest",description:"查看最新内容"},{command:"channels",description:"查看频道列表"},{command:"help",description:"查看使用说明"}]});}catch(_){}await tg(env,"sendMessage",{chat_id:chatId,text:"🔎 <b>频道历史内容检索助手</b>\n\n/search 关键词\n/search @频道 关键词\n/latest 查看最新\n/channels 查看可检索频道\n\n支持中文关键词、频道筛选、时间范围与媒体类型检索。",parse_mode:"HTML",reply_markup:{inline_keyboard:[[{text:"🔎 开始搜索",callback_data:"search:again"},{text:"📚 频道列表",callback_data:"channels:0"}],[{text:"🆕 最新内容",callback_data:"latest:0"}]]}});return json({ok:true});}
if(text==="/latest"){await sendLatest(env,chatId);return json({ok:true});}if(text==="/channels"){await sendChannels(env,chatId);return json({ok:true});}
if(/^\/(search|s)(?:@\w+)?(?:\s|$)/i.test(text)){let q=text.replace(/^\/(search|s)(?:@\w+)?\s*/i,"").trim();let channel="";const m=q.match(/^(@[A-Za-z0-9_]{3,})\s+(.+)$/);if(m){channel=m[1].slice(1);q=m[2].trim();}if(!q){await tg(env,"sendMessage",{chat_id:chatId,text:"请输入关键词，例如：/search AI 工具"});return json({ok:true});}const r=await search(env,{q,channel,limit:8,offset:0});await saveSession(env,chatId,{q,channel,offset:0,mode:"search"});await sendSearch(env,chatId,{...r,q});return json({ok:true});}
await tg(env,"sendMessage",{chat_id:chatId,text:"请输入 /search 关键词，或发送 /help 查看用法。"});return json({ok:true});}
async function apiSearch(req,env){const u=new URL(req.url);return json({query:u.searchParams.get("q")||"",...await search(env,{q:u.searchParams.get("q"),channel:u.searchParams.get("channel"),from:u.searchParams.get("from"),to:u.searchParams.get("to"),media:u.searchParams.get("media"),limit:u.searchParams.get("limit"),offset:u.searchParams.get("offset")})});}
async function apiLatest(req,env){const u=new URL(req.url);return json(await latest(env,{limit:u.searchParams.get("limit"),offset:u.searchParams.get("offset"),channel:u.searchParams.get("channel"),media:u.searchParams.get("media")}));}
async function apiChannels(req,env){return json({channels:await channels(env,true)});}
async function publicAddChannel(req,env){
  if(req.method!=="POST")return json({error:"method_not_allowed"},405);
  const b=await req.json().catch(()=>({}));
  const username=clean(b.username||b.telegram_id||"").replace(/^https?:\/\/t\.me\//,"" ).replace(/^@/,"").replace(/\/$/,"");
  const title=clean(b.title||username).slice(0,160);
  const code=codeNormalize(b.auth_code||"");
  if(!username)return json({error:"username_required",message:"请输入频道用户名。"},400);
  if(!/^[A-Za-z0-9_]{3,64}$/.test(username))return json({error:"invalid_username",message:"频道用户名格式不正确。"},400);
  if(!code)return json({error:"auth_code_required",message:"请输入授权码。"},400);
  const existing=await env.DB.prepare("SELECT id FROM channels WHERE username=? OR telegram_id=? LIMIT 1").bind(username,username).first();
  if(existing)return json({ok:true,already_exists:true,message:"频道已经存在，无需重复添加。"});
  const hash=await sha256Hex(code);
  const claim=await env.DB.prepare(`UPDATE auth_codes SET used_count=used_count+1,last_used_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE code_hash=? AND enabled=1 AND (max_uses IS NULL OR used_count<max_uses) AND (expires_at IS NULL OR expires_at>CURRENT_TIMESTAMP)`).bind(hash).run();
  if(Number(claim.meta?.changes||0)!==1)return json({error:"invalid_auth_code",message:"授权码无效、已停用、已过期或使用次数已达上限。"},403);
  try{
    await env.DB.prepare(`INSERT INTO channels(telegram_id,username,title,enabled)VALUES(?,?,?,1)`).bind(username,username,title).run();
    const c=await env.DB.prepare("SELECT id,used_count FROM auth_codes WHERE code_hash=? LIMIT 1").bind(hash).first();
    if(c)await env.DB.prepare("INSERT INTO auth_code_uses(code_id,action,ip,user_agent)VALUES(?,?,?,?)").bind(c.id,"add_channel",req.headers.get("CF-Connecting-IP")||req.headers.get("x-forwarded-for")||null,(req.headers.get("user-agent")||"").slice(0,500)).run();
    return json({ok:true,message:"频道添加成功，后续采集任务会自动同步。"});
  }catch(e){
    // Roll back only when the counter still matches the claim we just made.
    // If another request has consumed the same code concurrently, leave its count untouched.
    const claimed=await env.DB.prepare("SELECT used_count FROM auth_codes WHERE code_hash=? LIMIT 1").bind(hash).first();
    if(claimed?.used_count!=null){
      const n=Number(claimed.used_count);
      if(n>0)await env.DB.prepare("UPDATE auth_codes SET used_count=used_count-1,updated_at=CURRENT_TIMESTAMP WHERE code_hash=? AND used_count=?").bind(hash,n).run().catch(()=>{});
    }
    return json({error:"channel_create_failed",message:"频道添加失败，请稍后重试。"},409);
  }
}
const SUBMIT_HTML=`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#eef8ff"><title>提交频道 · Telegram Search</title><style>:root{font-family:Inter,-apple-system,BlinkMacSystemFont,"SF Pro Display","PingFang SC",sans-serif;color:#102a43;background:#f5faff}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(circle at 85% 0,#dff2ff,#f7fbff 38%,#fff 78%)}main{max-width:560px;margin:auto;padding:52px 18px}.brand{text-align:center;margin-bottom:28px}.logo{width:64px;height:64px;margin:0 auto 16px;border-radius:20px;background:#2e91f5;color:#fff;display:grid;place-items:center;font-size:34px;box-shadow:0 12px 28px rgba(46,145,245,.2)}h1{margin:0;font-size:30px;letter-spacing:-.5px}p{color:#7189a0;line-height:1.8}.panel{background:#fff;border:1px solid #dcecff;border-radius:24px;box-shadow:0 14px 36px rgba(49,128,205,.08);padding:22px}.field{margin-bottom:14px}.field label{display:block;font-size:13px;color:#5f7890;margin:0 0 7px}.field input{width:100%;border:1px solid #cfe2f5;border-radius:14px;padding:14px 15px;font:inherit;outline:none}.field input:focus{border-color:#5aaaf5;box-shadow:0 0 0 4px #eaf5ff}.btn{width:100%;border:0;border-radius:14px;padding:14px;background:#2e91f5;color:#fff;font-weight:750;font-size:15px;cursor:pointer}.msg{margin-top:12px;min-height:20px;font-size:13px;color:#7189a0}.back{display:block;text-align:center;margin-top:18px;color:#2e91f5;text-decoration:none;font-size:13px}</style></head><body><main><div class="brand"><div class="logo">➤</div><h1>提交频道</h1><p>使用有效授权码添加可检索的 Telegram 频道。</p></div><div class="panel"><div class="field"><label>频道</label><input id="channel" placeholder="@username 或 t.me/username" autocomplete="off"></div><div class="field"><label>授权码</label><input id="code" placeholder="请输入授权码" autocomplete="off" spellcheck="false"></div><div class="field"><label>频道显示名称（可选）</label><input id="title" placeholder="频道名称"></div><button class="btn" onclick="submitChannel()">验证并添加</button><div id="msg" class="msg"></div></div><a class="back" href="/">返回历史检索</a></main><script>const $=s=>document.querySelector(s);const clean=s=>String(s||'').trim();async function submitChannel(){const username=clean($('#channel').value),auth_code=clean($('#code').value),title=clean($('#title').value);$('#msg').textContent='正在验证…';try{const r=await fetch('/api/public/channels',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({username,auth_code,title})});const d=await r.json();$('#msg').textContent=r.ok?(d.message||'频道添加成功。'):(d.message||d.error||'添加失败。');if(r.ok){$('#channel').value='';$('#code').value='';$('#title').value='';}}catch(e){$('#msg').textContent='网络错误，请稍后重试。'}}</script></body></html>`;

async function adminChannels(req,env){
  if(!requireAdmin(req,env))return json({error:"unauthorized"},401);
  if(req.method==="GET")return json({channels:await channels(env,false)});
  const b=await req.json().catch(()=>({}));
  // 管理后台已经通过 ADMIN_TOKEN 完成身份认证；管理员添加频道无需额外授权码。
  const username=clean(b.username||b.telegram_id||"").replace(/^https?:\/\/t\.me\//,"" ).replace(/^@/,"").replace(/\/$/,"");
  if(!username)return json({error:"username_required"},400);
  const telegramId=clean(b.telegram_id||username);const title=clean(b.title||username);
  await env.DB.prepare(`INSERT INTO channels(telegram_id,username,title,enabled)VALUES(?,?,?,1) ON CONFLICT(telegram_id)DO UPDATE SET username=excluded.username,title=excluded.title,enabled=1,updated_at=CURRENT_TIMESTAMP`).bind(telegramId,username,title).run();
  return json({ok:true});
}
async function adminAuthCodes(req,env){
  if(!requireSuperAdmin(req,env))return json({error:"unauthorized"},401);
  if(req.method==="GET"){const r=await env.DB.prepare(`SELECT id,label,max_uses,used_count,expires_at,enabled,created_at,last_used_at FROM auth_codes ORDER BY created_at DESC`).all();return json({codes:r.results||[]});}
  if(req.method!=="POST")return json({error:"method_not_allowed"},405);
  const b=await req.json().catch(()=>({}));const label=clean(b.label||"未命名授权码").slice(0,80);const maxUses=b.max_uses==null||b.max_uses===""?null:Math.max(1,Number(b.max_uses)||1);
  let expiresAt=null;if(b.expires_at){const d=new Date(b.expires_at);if(Number.isNaN(d.getTime()))return json({error:"invalid_expires_at"},400);expiresAt=d.toISOString();}
  const code=codeNormalize(b.code||randomCode());if(code.length<8||code.length>120)return json({error:"invalid_code_length"},400);const hash=await sha256Hex(code);
  try{const r=await env.DB.prepare(`INSERT INTO auth_codes(label,code_hash,max_uses,expires_at,enabled)VALUES(?,?,?,?,1)`).bind(label,hash,maxUses,expiresAt).run();return json({ok:true,id:r.meta?.last_row_id||null,code});}catch(e){return json({error:"code_create_failed",message:"授权码已存在或无法创建。"},409);}
}
async function adminAuthCode(req,env,id){
  if(!requireSuperAdmin(req,env))return json({error:"unauthorized"},401);
  if(req.method!=="PATCH"&&req.method!=="DELETE")return json({error:"method_not_allowed"},405);
  const existing=await env.DB.prepare("SELECT id FROM auth_codes WHERE id=?").bind(id).first();if(!existing)return json({error:"not_found"},404);
  if(req.method==="DELETE"){await env.DB.prepare("DELETE FROM auth_codes WHERE id=?").bind(id).run();return json({ok:true});}
  const b=await req.json().catch(()=>({}));if(b.enabled==null)return json({error:"enabled_required"},400);await env.DB.prepare("UPDATE auth_codes SET enabled=?,updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(b.enabled?1:0,id).run();return json({ok:true});
}

async function adminChannel(req,env,id){if(!requireAdmin(req,env))return json({error:"unauthorized"},401);if(req.method==="PATCH"){const b=await req.json();if(b.enabled==null)return json({error:"enabled_required"},400);await env.DB.prepare("UPDATE channels SET enabled=?,updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(b.enabled?1:0,id).run();return json({ok:true});}if(req.method==="DELETE"){const c=await env.DB.prepare("SELECT telegram_id FROM channels WHERE id=?").bind(id).first();if(!c)return json({error:"not_found"},404);await env.DB.prepare("DELETE FROM messages WHERE channel_id=?").bind(c.telegram_id).run();await env.DB.prepare("DELETE FROM channels WHERE id=?").bind(id).run();return json({ok:true});}return json({error:"method_not_allowed"},405);}
async function dispatchCollector(req,env){
  if(!requireAdmin(req,env))return json({error:"unauthorized"},401);
  if(!env.GITHUB_TOKEN||!env.GITHUB_REPO)return json({error:"github_dispatch_not_configured",message:"请配置 GITHUB_TOKEN 与 GITHUB_REPO（owner/repo）"},503);
  const b=await req.json().catch(()=>({}));
  const target=clean(b.target_channel||"").replace(/^@/ ,"");
  const ref=clean(b.ref||env.GITHUB_REF||"main")||"main";
  const r=await fetch(`https://api.github.com/repos/${env.GITHUB_REPO}/actions/workflows/collector.yml/dispatches`,{method:"POST",headers:{Authorization:`Bearer ${env.GITHUB_TOKEN}`,Accept:"application/vnd.github+json","X-GitHub-Api-Version":"2022-11-28","content-type":"application/json"},body:JSON.stringify({ref,inputs:{target_channel:target}})});
  if(!r.ok)return json({error:"github_dispatch_failed",status:r.status,detail:(await r.text()).slice(0,500)},502);
  return json({ok:true,target_channel:target||null,ref});
}
async function retryRun(req,env,id){
  if(!requireAdmin(req,env))return json({error:"unauthorized"},401);
  const run=await env.DB.prepare("SELECT channel_id FROM collection_runs WHERE id=?").bind(id).first();
  if(!run)return json({error:"not_found"},404);
  const c=await env.DB.prepare("SELECT username,telegram_id FROM channels WHERE telegram_id=?").bind(String(run.channel_id)).first();
  return dispatchCollector(new Request(req.url,{method:"POST",headers:req.headers,body:JSON.stringify({target_channel:c?.username||c?.telegram_id||run.channel_id})}),env);
}
async function adminRuns(req,env){if(!requireAdmin(req,env))return json({error:"unauthorized"},401);const r=await env.DB.prepare(`SELECT cr.*,c.username,c.title FROM collection_runs cr LEFT JOIN channels c ON c.telegram_id=cr.channel_id ORDER BY cr.started_at DESC LIMIT 30`).all();return json({runs:r.results||[]});}
async function adminSession(req,env){const role=adminRole(req,env);if(!role)return json({error:"unauthorized"},401);return json({ok:true,role});}
async function adminStats(req,env){if(!requireAdmin(req,env))return json({error:"unauthorized"},401);const [m,c,e,l,r,p,v]=await Promise.all([env.DB.prepare("SELECT COUNT(*) count FROM messages").first(),env.DB.prepare("SELECT COUNT(*) count FROM channels").first(),env.DB.prepare("SELECT COUNT(*) count FROM channels WHERE enabled=1").first(),env.DB.prepare("SELECT MAX(published_at) published_at FROM messages").first(),env.DB.prepare("SELECT status,COUNT(*) count FROM collection_runs GROUP BY status").all(),env.DB.prepare("SELECT COUNT(*) count FROM messages WHERE media_type IS NOT NULL").first(),env.DB.prepare("SELECT media_type,COUNT(*) count FROM messages WHERE media_type IS NOT NULL GROUP BY media_type ORDER BY count DESC").all()]);return json({messages:Number(m?.count||0),channels:Number(c?.count||0),enabled_channels:Number(e?.count||0),last_published_at:l?.published_at||null,runs:r.results||[],media_messages:Number(p?.count||0),media_breakdown:v.results||[]});}
async function adminProgress(req,env){
  if(!requireAdmin(req,env))return json({error:"unauthorized"},401);
  const r=await env.DB.prepare(`SELECT cr.id,cr.channel_id,cr.status,cr.imported,cr.error,cr.started_at,cr.finished_at,c.username,c.title FROM collection_runs cr LEFT JOIN channels c ON c.telegram_id=cr.channel_id ORDER BY cr.started_at DESC LIMIT 12`).all();
  return json({runs:r.results||[]});
}
async function collectorChannels(req,env){if(!requireCollector(req,env))return json({error:"unauthorized"},401);return json({channels:(await channels(env,true)).map(x=>({telegram_id:x.telegram_id,username:x.username,title:x.title,last_message_id:x.last_message_id}))});}
async function runStart(req,env){if(!requireCollector(req,env))return json({error:"unauthorized"},401);const b=await req.json();const r=await env.DB.prepare("INSERT INTO collection_runs(channel_id,status)VALUES(?,?)").bind(String(b.channel_id||""),"running").run();return json({ok:true,run_id:r.meta?.last_row_id||null});}
async function runFinish(req,env){if(!requireCollector(req,env))return json({error:"unauthorized"},401);const b=await req.json();await env.DB.prepare("UPDATE collection_runs SET status=?,imported=?,error=?,finished_at=CURRENT_TIMESTAMP WHERE id=?").bind(b.status||"success",Number(b.imported||0),b.error||null,Number(b.run_id)).run();return json({ok:true});}
async function ingest(req,env){if(!requireCollector(req,env))return json({error:"unauthorized"},401);const b=await req.json();const messages=Array.isArray(b.messages)?b.messages:[];if(!messages.length)return json({ok:true,imported:0});const stmt=env.DB.prepare(`INSERT INTO messages(channel_id,channel_username,channel_title,message_id,published_at,edited_at,text,media_type,media_name,media_size,message_url,search_text)VALUES(?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(channel_id,message_id)DO UPDATE SET channel_username=excluded.channel_username,channel_title=excluded.channel_title,published_at=excluded.published_at,edited_at=excluded.edited_at,text=excluded.text,media_type=excluded.media_type,media_name=excluded.media_name,media_size=excluded.media_size,message_url=excluded.message_url,search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP`);const batch=messages.slice(0,500).map(m=>stmt.bind(String(m.channel_id),m.channel_username||"",m.channel_title||"",Number(m.message_id),m.published_at||null,m.edited_at||null,m.text||"",m.media_type||null,m.media_name||null,m.media_size?Number(m.media_size):null,m.message_url||null,m.search_text||m.text||""));await env.DB.batch(batch);const cid=String(messages[0].channel_id);const maxId=Math.max(...messages.map(m=>Number(m.message_id)||0));await env.DB.prepare(`INSERT INTO channels(telegram_id,username,title,last_message_id,message_count,last_synced_at)VALUES(?,?,?,?,(SELECT COUNT(*) FROM messages WHERE channel_id=?),CURRENT_TIMESTAMP) ON CONFLICT(telegram_id)DO UPDATE SET username=CASE WHEN excluded.username!='' THEN excluded.username ELSE channels.username END,title=CASE WHEN excluded.title!='' THEN excluded.title ELSE channels.title END,last_message_id=MAX(channels.last_message_id,excluded.last_message_id),message_count=(SELECT COUNT(*) FROM messages WHERE channel_id=excluded.telegram_id),last_synced_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP`).bind(cid,messages[0].channel_username||"",messages[0].channel_title||"",maxId,cid).run();return json({ok:true,imported:batch.length,channel_id:cid,max_message_id:maxId});}
const LOGIN_HTML=`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>管理员登录 · Telegram History Search</title><style>:root{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC",sans-serif;color:#102a43;background:#eef7ff}*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;padding:24px;background:radial-gradient(circle at 15% 10%,#d9efff,transparent 38%),linear-gradient(135deg,#f8fcff,#eaf5ff)}.card{width:min(440px,100%);background:#fff;border:1px solid #d9ebfa;border-radius:26px;padding:34px;box-shadow:0 24px 70px rgba(35,110,170,.15)}.brand{display:flex;align-items:center;gap:12px;margin-bottom:34px}.logo{width:46px;height:46px;display:grid;place-items:center;border-radius:15px;background:linear-gradient(145deg,#2d9af7,#167de0);color:#fff;font-size:22px}.eyebrow{color:#278ce8;font-size:11px;font-weight:800;letter-spacing:1.5px}.title{font-size:28px;letter-spacing:-.8px;margin:8px 0}.sub{color:#7b92a7;font-size:13px;line-height:1.7}.label{display:block;color:#496a84;font-size:12px;font-weight:750;margin:22px 0 8px}.input{width:100%;height:48px;border:1px solid #cfe3f5;border-radius:13px;padding:0 14px;outline:none;font-size:14px}.input:focus{border-color:#3a99f0;box-shadow:0 0 0 4px #eaf5ff}.btn{width:100%;height:48px;border:0;border-radius:13px;background:#238df2;color:#fff;font-weight:800;margin-top:16px;cursor:pointer}.btn:disabled{opacity:.65;cursor:wait}.msg{min-height:22px;color:#d4515b;font-size:12px;margin-top:12px}.note{border-top:1px solid #edf4fa;margin-top:28px;padding-top:18px;color:#9aabba;font-size:11px;line-height:1.7}</style><style>body{background:radial-gradient(circle at 10% 0%,#dff1ff 0,transparent 32%),radial-gradient(circle at 100% 100%,#dfe7ff 0,transparent 30%),#f4f8fc}.card{width:min(456px,100%);padding:42px 40px 32px;border:1px solid rgba(255,255,255,.9);border-radius:28px;box-shadow:0 30px 80px rgba(24,69,114,.18)}.brand{margin-bottom:38px}.logo{width:50px;height:50px;border-radius:16px;box-shadow:0 12px 24px rgba(35,141,242,.28)}.eyebrow{font-size:10px;letter-spacing:2px}.title{font-size:30px;color:#122c47;margin:0 0 8px;text-align:center}.sub{color:#71889d}.card>p.sub{text-align:center;white-space:nowrap;font-size:clamp(10px,2.9vw,13px)}.label{margin-top:28px;color:#385b76}.input{height:52px;background:#f9fcff;border-color:#d6e5f1;border-radius:14px;font-size:16px}.btn{height:52px;margin-top:18px;border-radius:14px;background:linear-gradient(135deg,#288ff4,#176fd3);box-shadow:0 12px 24px rgba(35,141,242,.22);transition:transform .18s,box-shadow .18s}.btn:hover{transform:translateY(-1px);box-shadow:0 16px 28px rgba(35,141,242,.28)}.note{margin-top:32px}html,body{height:100%;overflow:hidden}body{min-height:100dvh;padding:16px}.card{max-height:calc(100dvh - 32px);overflow:hidden}@media(max-width:480px){.card{padding:28px 22px 24px}.brand{margin-bottom:26px}.title{font-size:27px}.label{margin-top:20px}}</style></head><body><main class="card"><div class="brand"><div class="logo">✈</div><div><div class="eyebrow">TELEGRAM HISTORY SEARCH</div><div class="sub">安全管理控制台</div></div></div><h1 class="title">管理员登录</h1><p class="sub">登录后管理频道、执行同步任务并查看采集状态。</p><label class="label" for="token">管理员令牌</label><input id="token" class="input" type="password" autocomplete="current-password" placeholder="请输入 ADMIN_TOKEN"><button id="login" class="btn">登录后台</button><div id="msg" class="msg"></div></main><script>const tokenInput=document.getElementById('token'),loginButton=document.getElementById('login'),msg=document.getElementById('msg');async function login(){const token=tokenInput.value.trim();if(!token){msg.textContent='请输入管理员令牌。';return}loginButton.disabled=true;loginButton.textContent='验证中…';msg.textContent='';try{const r=await fetch('/api/admin/session',{headers:{'x-admin-token':token}});const d=await r.json();if(!r.ok)throw Error('invalid');localStorage.setItem('tg_admin_token',token);localStorage.setItem('tg_admin_role',d.role||'admin');location.href='/admin'}catch(e){msg.textContent='令牌无效或服务暂时不可用，请检查后重试。';loginButton.disabled=false;loginButton.textContent='登录后台'}}loginButton.addEventListener('click',login);tokenInput.addEventListener('keydown',e=>{if(e.key==='Enter')login()});</script></body></html>`;
const AUTH_HTML=`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>授权管理 · Telegram History Search</title><style>:root{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC",sans-serif;color:#102a43;background:#f4f8fc}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:linear-gradient(135deg,#edf7ff,#f8fbff)}.wrap{width:min(920px,calc(100% - 32px));margin:0 auto;padding:36px 0}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:24px}.brand{display:flex;gap:12px;align-items:center}.logo{width:44px;height:44px;display:grid;place-items:center;border-radius:14px;background:linear-gradient(145deg,#2b9af7,#167fe4);color:#fff;font-size:20px}.eyebrow{font-size:10px;letter-spacing:1.5px;color:#238df2;font-weight:800}.title{font-size:26px;margin:5px 0 0}.back{color:#238df2;text-decoration:none;font-size:13px;font-weight:750}.card{background:#fff;border:1px solid #dceafa;border-radius:20px;padding:24px;box-shadow:0 14px 34px rgba(35,100,150,.08)}.sub{color:#7890a6;font-size:13px}.form{display:grid;grid-template-columns:1fr 160px 190px auto;gap:10px;margin-top:20px}.input{height:44px;border:1px solid #cfe1f2;border-radius:11px;padding:0 12px;font-size:14px;outline:0}.input:focus{border-color:#238df2;box-shadow:0 0 0 4px #eaf4ff}.btn{height:44px;border:0;border-radius:11px;background:#238df2;color:#fff;font-weight:750;padding:0 16px;cursor:pointer}.msg{min-height:20px;color:#55728a;font-size:12px;margin-top:10px}.list{margin-top:24px;border-top:1px solid #edf3f8}.item{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:16px 0;border-bottom:1px solid #edf3f8}.meta{color:#7890a6;font-size:12px;margin-top:5px}.badge{color:#16865a;background:#eaf9f2;border-radius:8px;padding:5px 8px;font-size:11px}@media(max-width:700px){.wrap{padding:20px 0}.top{align-items:flex-start}.form{grid-template-columns:1fr}.btn{width:100%}.item{align-items:flex-start;flex-direction:column}}</style></head><body><main class="wrap"><div class="top"><div class="brand"><div class="logo">✈</div><div><div class="eyebrow">TELEGRAM HISTORY SEARCH</div><h1 class="title">授权管理</h1></div></div><a class="back" href="/admin">← 返回管理后台</a></div><section class="card"><div class="eyebrow">ACCESS CONTROL</div><h2>授权码</h2><p class="sub">授权码仅用于允许外部用户提交频道，不影响管理员登录和频道同步。</p><div class="form"><input id="label" class="input" placeholder="授权码名称"><input id="max" class="input" type="number" min="1" placeholder="次数上限"><input id="expire" class="input" type="datetime-local"><button id="create" class="btn">生成授权码</button></div><div id="msg" class="msg"></div><div id="list" class="list">加载中…</div></section></main><script>const token=localStorage.getItem('tg_admin_token')||'',headers={'content-type':'application/json','x-admin-token':token},$=s=>document.querySelector(s);async function api(u,o={}){const r=await fetch(u,{...o,headers:{...headers,...(o.headers||{})}});if(r.status===401){localStorage.removeItem('tg_admin_token');location.href='/admin/login';throw Error('unauthorized')}return r.json()}async function load(){try{const r=await api('/api/admin/auth-codes');$('#list').innerHTML=(r.codes||[]).map(x=>'<div class="item"><div><strong>'+String(x.label||'未命名')+'</strong><div class="meta">已使用 '+Number(x.used_count||0)+' / '+(x.max_uses==null?'不限':x.max_uses)+(x.expires_at?' · 到期 '+new Date(x.expires_at).toLocaleString():' · 永不过期')+'</div></div><span class="badge">'+(x.enabled?'启用':'停用')+'</span></div>').join('')||'<div class="sub">暂无授权码</div>'}catch(e){$('#list').textContent='无法读取授权码，请重新登录。'}}$('#create').onclick=async()=>{const body={label:$('#label').value.trim()};if($('#max').value)body.max_uses=Number($('#max').value);if($('#expire').value)body.expires_at=new Date($('#expire').value).toISOString();if(!body.label){$('#msg').textContent='请先填写授权码名称。';return}const r=await api('/api/admin/auth-codes',{method:'POST',body:JSON.stringify(body)});$('#msg').textContent=r.ok?'授权码已生成，请在列表中查看。':(r.message||r.error||'生成失败。');if(r.ok){$('#label').value='';$('#max').value='';$('#expire').value='';load()}};if(!token)location.href='/admin/login';else api('/api/admin/session').then(s=>{if(s.role==='super_admin')load();else document.body.innerHTML='<main style="max-width:560px;margin:15vh auto;padding:32px;text-align:center;font-family:sans-serif"><h1>无权访问</h1><p>授权管理仅限超级管理员使用。</p><a href="/admin">返回管理后台</a></main>'}).catch(()=>{});</script></body></html>`;
